   "source": [
    "library(tidyverse)\n",
    "library(lubridate)\n",
    "library(janitor)\n",
    "\n",
    "set.seed(42)\n",
    "\n",
    "# ----------------------------\n",
    "# 1) CONFIG\n",
    "# ----------------------------\n",
    "n <- 1200  # number of excursion events\n",
    "\n",
    "facilities <- c(\"HCMC_DC_01\", \"HCMC_DC_02\", \"BinhDuong_DC_01\", \"CanTho_DC_01\", \"Hanoi_DC_01\")\n",
    "lanes <- c(\"DC_to_Retail\", \"Port_to_DC\", \"DC_to_FoodService\", \"CrossDock\", \"Supplier_to_DC\")\n",
    "products <- c(\"RTE_Salad\", \"Dairy\", \"Frozen\", \"Seafood\", \"Meat\", \"Produce\", \"Dessert\")\n",
    "ca_types <- c(\"Process\", \"Training\", \"Engineering\", \"Supplier\", \"Equipment_Maint\")\n",
    "\n",
    "# Severity distribution (more Minor than Major, more Major than Critical)\n",
    "severity <- sample(\n",
    "  c(\"Minor\", \"Major\", \"Critical\"),\n",
    "  size = n,\n",
    "  replace = TRUE,\n",
    "  prob = c(0.62, 0.30, 0.08)\n",
    ")\n",
    "\n",
    "# Make some facilities/lanes slightly \"riskier\" (more repeats / higher excursion minutes)\n",
    "facility <- sample(facilities, n, replace = TRUE, prob = c(0.28, 0.22, 0.20, 0.15, 0.15))\n",
    "lane <- sample(lanes, n, replace = TRUE, prob = c(0.35, 0.22, 0.18, 0.15, 0.10))\n",
    "product <- sample(products, n, replace = TRUE)\n",
    "\n",
    "# Date range for events\n",
    "start_date <- as.Date(\"2025-06-01\")\n",
    "end_date   <- as.Date(\"2026-02-18\")\n",
    "event_date <- sample(seq.Date(start_date, end_date, by = \"day\"), n, replace = TRUE)\n",
    "\n",
    "# Excursion duration in minutes: depends on severity + facility/lane risk\n",
    "risk_facility_boost <- case_when(\n",
    "  facility %in% c(\"HCMC_DC_01\", \"BinhDuong_DC_01\") ~ 1.15,\n",
    "  TRUE ~ 1.00\n",
    ")\n",
    "\n",
    "risk_lane_boost <- case_when(\n",
    "  lane %in% c(\"Port_to_DC\", \"CrossDock\") ~ 1.20,\n",
    "  TRUE ~ 1.00\n",
    ")\n",
    "\n",
    "base_minutes <- case_when(\n",
    "  severity == \"Minor\"    ~ rlnorm(n, meanlog = log(18), sdlog = 0.55),\n",
    "  severity == \"Major\"    ~ rlnorm(n, meanlog = log(55), sdlog = 0.60),\n",
    "  severity == \"Critical\" ~ rlnorm(n, meanlog = log(140), sdlog = 0.70)\n",
    ")\n",
    "\n",
    "excursion_minutes <- round(base_minutes * risk_facility_boost * risk_lane_boost)\n",
    "\n",
    "# Temperature deviation (°C above spec): severity-driven\n",
    "temp_deviation_c <- case_when(\n",
    "  severity == \"Minor\"    ~ pmax(0.5, rnorm(n, mean = 1.5, sd = 0.7)),\n",
    "  severity == \"Major\"    ~ pmax(1.5, rnorm(n, mean = 3.5, sd = 1.0)),\n",
    "  severity == \"Critical\" ~ pmax(3.0, rnorm(n, mean = 6.0, sd = 1.5))\n",
    ") %>% round(1)\n",
    "\n",
    "# Corrective action type: more Engineering/Equipment for severe, more Training/Process for minor\n",
    "corrective_action_type <- map_chr(severity, ~{\n",
    "  if (.x == \"Minor\") sample(c(\"Training\", \"Process\", \"Equipment_Maint\"), 1, prob = c(0.45, 0.40, 0.15))\n",
    "  else if (.x == \"Major\") sample(c(\"Process\", \"Engineering\", \"Equipment_Maint\", \"Supplier\"), 1, prob = c(0.35, 0.30, 0.20, 0.15))\n",
    "  else sample(c(\"Engineering\", \"Equipment_Maint\", \"Supplier\", \"Process\"), 1, prob = c(0.40, 0.30, 0.20, 0.10))\n",
    "})\n",
    "\n",
    "# ----------------------------\n",
    "# 2) CAPA CLOSURE TIME MODEL\n",
    "# ----------------------------\n",
    "# We intentionally create a realistic \"fatigue\" pattern:\n",
    "# - Critical SHOULD close fastest, but sometimes closes slower due to approvals/vendor waits.\n",
    "# - Major often closes slower than minor.\n",
    "# - Engineering/Supplier actions tend to take longer.\n",
    "ca_time_multiplier <- case_when(\n",
    "  corrective_action_type == \"Training\"          ~ 0.75,\n",
    "  corrective_action_type == \"Process\"           ~ 1.00,\n",
    "  corrective_action_type == \"Equipment_Maint\"   ~ 1.20,\n",
    "  corrective_action_type == \"Engineering\"       ~ 1.40,\n",
    "  corrective_action_type == \"Supplier\"          ~ 1.55,\n",
    "  TRUE ~ 1.00\n",
    ")\n",
    "\n",
    "# Severity baseline in days (with noise)\n",
    "severity_base_days <- case_when(\n",
    "  severity == \"Minor\"    ~ rlnorm(n, log(10), 0.40),\n",
    "  severity == \"Major\"    ~ rlnorm(n, log(16), 0.45),\n",
    "  severity == \"Critical\" ~ rlnorm(n, log(14), 0.55) # intentionally not always fastest\n",
    ")\n",
    "\n",
    "# Add facility friction (a couple of sites have slower closure)\n",
    "facility_friction <- case_when(\n",
    "  facility %in% c(\"HCMC_DC_01\") ~ 1.20,\n",
    "  facility %in% c(\"CanTho_DC_01\") ~ 1.10,\n",
    "  TRUE ~ 1.00\n",
    ")\n",
    "\n",
    "capa_days <- round(severity_base_days * ca_time_multiplier * facility_friction)\n",
    "\n",
    "# CAPA open date: usually within 0-2 days of event\n",
    "capa_open_date <- event_date + sample(0:2, n, replace = TRUE, prob = c(0.55, 0.30, 0.15))\n",
    "capa_close_date <- capa_open_date + capa_days\n",
    "\n",
    "# Repeat excursion flag: more likely in \"riskier\" combinations + slower CAPA closure\n",
    "repeat_prob <- plogis(\n",
    "  -2.0 +\n",
    "    0.012 * pmin(excursion_minutes, 400) +\n",
    "    0.04  * (severity == \"Major\") +\n",
    "    0.12  * (severity == \"Critical\") +\n",
    "    0.20  * (facility %in% c(\"HCMC_DC_01\", \"BinhDuong_DC_01\")) +\n",
    "    0.18  * (lane %in% c(\"Port_to_DC\", \"CrossDock\")) +\n",
    "    0.015 * pmin(capa_days, 60)\n",
    ")\n",
    "\n",
    "is_repeat <- rbinom(n, size = 1, prob = repeat_prob)\n",
    "\n",
    "# Some audit / detection channel\n",
    "detection_channel <- sample(\n",
    "  c(\"DataLogger_Alert\", \"Receiving_Check\", \"Internal_Audit\", \"Customer_Complaint\", \"Driver_Report\"),\n",
    "  n,\n",
    "  replace = TRUE,\n",
    "  prob = c(0.40, 0.25, 0.15, 0.10, 0.10)\n",
    ")\n",
    "\n",
    "# Assemble dataset\n",
    "cold_chain_events <- tibble(\n",
    "  excursion_id = sprintf(\"EX%05d\", 1:n),\n",
    "  event_date = event_date,\n",
    "  facility = facility,\n",
    "  lane = lane,\n",
    "  product = product,\n",
    "  severity = factor(severity, levels = c(\"Minor\", \"Major\", \"Critical\")),\n",
    "  excursion_minutes = excursion_minutes,\n",
    "  temp_deviation_c = temp_deviation_c,\n",
    "  detection_channel = detection_channel,\n",
    "  corrective_action_type = corrective_action_type,\n",
    "  capa_open_date = capa_open_date,\n",
    "  capa_close_date = capa_close_date,\n",
    "  capa_days = as.numeric(capa_close_date - capa_open_date),\n",
    "  is_repeat = is_repeat\n",
    ") %>%\n",
    "  clean_names()\n",
    "\n",
    "glimpse(cold_chain_events)\n",
    "\n",
    "# Optional: write to CSV for portfolio artifact\n",
    "# write_csv(cold_chain_events, \"cold_chain_events_v1.csv\")\n",
    "\n",
    "# ----------------------------\n",
    "# 3) YOUR CHOSEN ANALYSIS (C): CAPA DAYS vs SEVERITY\n",
    "# ----------------------------\n",
    "severity_capa_summary <- cold_chain_events %>%\n",
    "  group_by(severity) %>%\n",
    "  summarise(\n",
    "    avg_capa_days = mean(capa_days, na.rm = TRUE),\n",
    "    median_capa_days = median(capa_days, na.rm = TRUE),\n",
    "    p90_capa_days = quantile(capa_days, 0.90, na.rm = TRUE),\n",
    "    count = n(),\n",
    "    repeat_rate = mean(is_repeat, na.rm = TRUE)\n",
    "  ) %>%\n",
    "  arrange(severity)\n",
    "\n",
    "severity_capa_summary\n",
    "\n",
    "ggplot(cold_chain_events, aes(x = severity, y = capa_days)) +\n",
    "  geom_boxplot() +\n",
    "  labs(\n",
    "    title = \"CAPA Closure Time by Excursion Severity\",\n",
    "    subtitle = \"Synthetic dataset designed to surface systemic fatigue patterns (approval/vendor bottlenecks, site friction)\",\n",
    "    x = \"Excursion Severity\",\n",
    "    y = \"Days to Close CAPA\"\n",
    "  ) +\n",
    "  theme_minimal()\n",
    "\n",
    "# Extra: severity vs repeat_rate (ties to your preventative systems series)\n",
    "cold_chain_events %>%\n",
    "  group_by(severity) %>%\n",
    "  summarise(repeat_rate = mean(is_repeat)) %>%\n",
    "  arrange(severity)\n"
   ]
  },
