    "# ----------------------------\n",
    "# EARLY WARNING INDEX (EWI)\n",
    "# ----------------------------\n",
    "\n",
    "facility_metrics <- cold_chain_events %>%\n",
    "  group_by(facility) %>%\n",
    "  summarise(\n",
    "    avg_capa_days = mean(capa_days, na.rm = TRUE),\n",
    "    repeat_rate = mean(is_repeat, na.rm = TRUE),\n",
    "    avg_excursion_minutes = mean(excursion_minutes, na.rm = TRUE),\n",
    "    critical_rate = mean(severity == \"Critical\"),\n",
    "    n_events = n()\n",
    "  ) %>%\n",
    "  ungroup()\n"
   ]
