    "normalize <- function(x) {\n",
    "  (x - min(x)) / (max(x) - min(x))\n",
    "}\n",
    "\n",
    "facility_metrics <- facility_metrics %>%\n",
    "  mutate(\n",
    "    norm_capa = normalize(avg_capa_days),\n",
    "    norm_repeat = normalize(repeat_rate),\n",
    "    norm_minutes = normalize(avg_excursion_minutes),\n",
    "    norm_critical = normalize(critical_rate)\n",
    "  )\n"
   ]
