   "outputs": [],
   "source": [
    "reporting_delay = as.numeric(capa_open_date - event_date)\n",
    "\n",
    "reporting_metrics <- cold_chain_events %>%\n",
    "  mutate(reporting_delay = as.numeric(capa_open_date - event_date)) %>%\n",
    "  group_by(facility) %>%\n",
    "  summarise(\n",
    "    avg_reporting_delay = mean(reporting_delay, na.rm = TRUE),\n",
    "    pct_same_day = mean(reporting_delay == 0),\n",
    "    event_volume = n()\n",
    "  )\n"
   ]
  },
