   "source": [
    "reporting_metrics_long <- reporting_metrics %>%\n",
    "  select(facility, avg_reporting_delay, pct_same_day) %>%\n",
    "  pivot_longer(-facility,\n",
    "               names_to = \"metric\",\n",
    "               values_to = \"value\")\n",
    "\n",
    "ggplot(reporting_metrics_long,\n",
    "       aes(x = facility, y = value)) +\n",
    "  geom_col() +\n",
    "  facet_wrap(~metric, scales = \"free_y\") +\n",
    "  coord_flip() +\n",
    "  labs(\n",
    "    title = \"Reporting Integrity Metrics by Facility\",\n",
    "    x = \"Facility\",\n",
    "    y = \"Value\"\n",
    "  ) +\n",
    "  theme_minimal()\n"
   ]
  },
