   "source": [
    "library(tidyverse)\n",
    "library(lubridate)\n",
    "library(janitor)\n",
    "library(scales)\n",
    "\n",
    "# ---------------------------------------\n",
    "# GOVERNANCE LAYER: REPORTING INTEGRITY\n",
    "# ---------------------------------------\n",
    "\n",
    "# 1) Add reporting_delay (days) at the event level\n",
    "cold_chain_events <- cold_chain_events %>%\n",
    "  mutate(\n",
    "    reporting_delay = as.numeric(capa_open_date - event_date),\n",
    "    event_month = floor_date(event_date, \"month\")\n",
    "  )\n",
    "\n",
    "# 2) Facility-level reporting integrity metrics\n",
    "reporting_metrics <- cold_chain_events %>%\n",
    "  group_by(facility) %>%\n",
    "  summarise(\n",
    "    avg_reporting_delay = mean(reporting_delay, na.rm = TRUE),\n",
    "    median_reporting_delay = median(reporting_delay, na.rm = TRUE),\n",
    "    pct_same_day = mean(reporting_delay == 0, na.rm = TRUE),\n",
    "    pct_within_48h = mean(reporting_delay <= 2, na.rm = TRUE),\n",
    "    event_volume = n(),\n",
    "    .groups = \"drop\"\n",
    "  )\n",
    "\n",
    "reporting_metrics\n",
    "\n",
    "# --- Visualization A: Average Reporting Delay by Facility ---\n",
    "ggplot(reporting_metrics,\n",
    "       aes(x = reorder(facility, avg_reporting_delay),\n",
    "           y = avg_reporting_delay)) +\n",
    "  geom_col() +\n",
    "  coord_flip() +\n",
    "  labs(\n",
    "    title = \"Average Reporting Delay by Facility\",\n",
    "    subtitle = \"Days between excursion event date and CAPA open date\",\n",
    "    x = \"Facility\",\n",
    "    y = \"Average Reporting Delay (Days)\"\n",
    "  ) +\n",
    "  theme_minimal()\n",
    "\n",
    "# --- Visualization B: Same-Day Reporting Rate by Facility ---\n",
    "ggplot(reporting_metrics,\n",
    "       aes(x = reorder(facility, pct_same_day),\n",
    "           y = pct_same_day)) +\n",
    "  geom_col() +\n",
    "  coord_flip() +\n",
    "  scale_y_continuous(labels = percent_format()) +\n",
    "  labs(\n",
    "    title = \"Same-Day Reporting Rate by Facility\",\n",
    "    subtitle = \"Share of excursions logged on the same day as the event\",\n",
    "    x = \"Facility\",\n",
    "    y = \"Same-Day Reporting Rate\"\n",
    "  ) +\n",
    "  theme_minimal()\n",
    "\n",
    "# 3) Event volume trend over time (monthly)\n",
    "volume_trend <- cold_chain_events %>%\n",
    "  group_by(event_month) %>%\n",
    "  summarise(\n",
    "    event_volume = n(),\n",
    "    avg_reporting_delay = mean(reporting_delay, na.rm = TRUE),\n",
    "    .groups = \"drop\"\n",
    "  ) %>%\n",
    "  arrange(event_month)\n",
    "\n",
    "volume_trend\n",
    "\n",
    "# --- Visualization C: Event Volume Over Time (Monthly) ---\n",
    "ggplot(volume_trend, aes(x = event_month, y = event_volume)) +\n",
    "  geom_line() +\n",
    "  geom_point() +\n",
    "  labs(\n",
    "    title = \"Excursion Event Volume Over Time\",\n",
    "    subtitle = \"Monthly counts (drops may indicate underreporting or logging friction)\",\n",
    "    x = \"Month\",\n",
    "    y = \"Number of Excursions\"\n",
    "  ) +\n",
    "  theme_minimal()\n",
    "\n",
    "# --- Visualization D (Optional): Reporting Delay Over Time (Monthly) ---\n",
    "ggplot(volume_trend, aes(x = event_month, y = avg_reporting_delay)) +\n",
    "  geom_line() +\n",
    "  geom_point() +\n",
    "  labs(\n",
    "    title = \"Average Reporting Delay Over Time\",\n",
    "    subtitle = \"Monthly average days from event to CAPA open\",\n",
    "    x = \"Month\",\n",
    "    y = \"Average Reporting Delay (Days)\"\n",
    "  ) +\n",
    "  theme_minimal()\n"
   ]
